BEGIN EXECUTE IMMEDIATE 'CREATE TABLE INFRANEXUM_IAM_ACCESS_POLICY (ID VARCHAR2(36 CHAR) PRIMARY KEY, ORGANIZATION_ID VARCHAR2(36 CHAR), CODE VARCHAR2(128 CHAR) NOT NULL, POLICY_VERSION NUMBER(19) NOT NULL, OWNER_ID VARCHAR2(36 CHAR) NOT NULL, PURPOSE VARCHAR2(500 CHAR) NOT NULL, PRIORITY NUMBER(10) NOT NULL, SCOPE_KIND VARCHAR2(16 CHAR) NOT NULL, SUBDIVISION_ID VARCHAR2(36 CHAR), STATE VARCHAR2(16 CHAR) NOT NULL, EFFECTIVE_FROM TIMESTAMP(6) WITH TIME ZONE NOT NULL, APPROVED_BY VARCHAR2(36 CHAR), APPROVED_AT TIMESTAMP(6) WITH TIME ZONE, ACTIVATED_AT TIMESTAMP(6) WITH TIME ZONE, DEPRECATED_AT TIMESTAMP(6) WITH TIME ZONE, RETIRED_AT TIMESTAMP(6) WITH TIME ZONE, CREATED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL, UPDATED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL, CONSTRAINT CK_INX_IAM_POL_UUID CHECK (REGEXP_LIKE(ID,''^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'')), CONSTRAINT CK_INX_IAM_POL_VER CHECK (POLICY_VERSION>=1), CONSTRAINT CK_INX_IAM_POL_PRI CHECK (PRIORITY BETWEEN 0 AND 10000), CONSTRAINT CK_INX_IAM_POL_SCOPE CHECK (SCOPE_KIND IN (''PLATFORM'',''ORGANIZATION'',''SUBDIVISION'')), CONSTRAINT CK_INX_IAM_POL_PAIR CHECK ((SCOPE_KIND=''PLATFORM'' AND ORGANIZATION_ID IS NULL AND SUBDIVISION_ID IS NULL) OR (SCOPE_KIND=''ORGANIZATION'' AND ORGANIZATION_ID IS NOT NULL AND SUBDIVISION_ID IS NULL) OR (SCOPE_KIND=''SUBDIVISION'' AND ORGANIZATION_ID IS NOT NULL AND SUBDIVISION_ID IS NOT NULL)), CONSTRAINT CK_INX_IAM_POL_STATE CHECK (STATE IN (''DRAFT'',''VALIDATED'',''APPROVED'',''ACTIVE'',''DEPRECATED'',''RETIRED'')), CONSTRAINT CK_INX_IAM_POL_APPR CHECK ((APPROVED_BY IS NULL AND APPROVED_AT IS NULL) OR (APPROVED_BY IS NOT NULL AND APPROVED_AT IS NOT NULL)), CONSTRAINT CK_INX_IAM_POL_ACT CHECK (STATE NOT IN (''ACTIVE'',''DEPRECATED'',''RETIRED'') OR ACTIVATED_AT IS NOT NULL), CONSTRAINT CK_INX_IAM_POL_DEP CHECK (STATE NOT IN (''DEPRECATED'',''RETIRED'') OR DEPRECATED_AT IS NOT NULL), CONSTRAINT CK_INX_IAM_POL_RET CHECK (STATE<>''RETIRED'' OR RETIRED_AT IS NOT NULL), CONSTRAINT CK_INX_IAM_POL_TIME CHECK (UPDATED_AT>=CREATED_AT AND EFFECTIVE_FROM>=CREATED_AT))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/
BEGIN EXECUTE IMMEDIATE 'CREATE UNIQUE INDEX UQ_INX_IAM_POL_VERSION ON INFRANEXUM_IAM_ACCESS_POLICY(NVL(ORGANIZATION_ID,''~PLATFORM~''),CODE,POLICY_VERSION)'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/
BEGIN EXECUTE IMMEDIATE 'CREATE UNIQUE INDEX UQ_INX_IAM_POL_ACTIVE ON INFRANEXUM_IAM_ACCESS_POLICY(CASE WHEN STATE=''ACTIVE'' THEN NVL(ORGANIZATION_ID,''~PLATFORM~'') END,CASE WHEN STATE=''ACTIVE'' THEN CODE END)'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/
BEGIN EXECUTE IMMEDIATE 'CREATE INDEX IX_INX_IAM_POL_SCOPE ON INFRANEXUM_IAM_ACCESS_POLICY(STATE,ORGANIZATION_ID,PRIORITY,CODE,POLICY_VERSION)'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/

BEGIN EXECUTE IMMEDIATE 'CREATE TABLE INFRANEXUM_IAM_ACCESS_POLICY_RULE (ID VARCHAR2(36 CHAR) PRIMARY KEY, POLICY_ID VARCHAR2(36 CHAR) NOT NULL, POSITION_NO NUMBER(10) NOT NULL, EFFECT VARCHAR2(8 CHAR) NOT NULL, ACTION_SELECTOR VARCHAR2(128 CHAR) NOT NULL, RESOURCE_TYPE VARCHAR2(80 CHAR) NOT NULL, OBLIGATIONS_CSV VARCHAR2(500 CHAR) DEFAULT '''' NOT NULL, ADVICE VARCHAR2(500 CHAR) DEFAULT '''' NOT NULL, CONSTRAINT FK_INX_IAM_POL_RULE FOREIGN KEY (POLICY_ID) REFERENCES INFRANEXUM_IAM_ACCESS_POLICY(ID) ON DELETE CASCADE, CONSTRAINT UQ_INX_IAM_POL_RULE_POS UNIQUE(POLICY_ID,POSITION_NO), CONSTRAINT CK_INX_IAM_POL_RULE_UUID CHECK (REGEXP_LIKE(ID,''^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'')), CONSTRAINT CK_INX_IAM_POL_RULE_POS CHECK (POSITION_NO BETWEEN 1 AND 10000), CONSTRAINT CK_INX_IAM_POL_RULE_EFF CHECK (EFFECT IN (''PERMIT'',''DENY'')))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/
BEGIN EXECUTE IMMEDIATE 'CREATE INDEX IX_INX_IAM_POL_RULE ON INFRANEXUM_IAM_ACCESS_POLICY_RULE(POLICY_ID,POSITION_NO)'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/

BEGIN EXECUTE IMMEDIATE 'CREATE TABLE INFRANEXUM_IAM_ACCESS_POLICY_CONDITION (RULE_ID VARCHAR2(36 CHAR) NOT NULL, POSITION_NO NUMBER(10) NOT NULL, SOURCE_NAME VARCHAR2(24 CHAR) NOT NULL, ATTRIBUTE_NAME VARCHAR2(64 CHAR) NOT NULL, OPERATOR_NAME VARCHAR2(16 CHAR) NOT NULL, EXPECTED_VALUE VARCHAR2(256 CHAR) NOT NULL, CONSTRAINT PK_INX_IAM_POL_COND PRIMARY KEY(RULE_ID,POSITION_NO), CONSTRAINT FK_INX_IAM_POL_COND FOREIGN KEY (RULE_ID) REFERENCES INFRANEXUM_IAM_ACCESS_POLICY_RULE(ID) ON DELETE CASCADE, CONSTRAINT CK_INX_IAM_POL_COND_POS CHECK (POSITION_NO BETWEEN 1 AND 32), CONSTRAINT CK_INX_IAM_POL_COND_SRC CHECK (SOURCE_NAME IN (''SUBJECT'',''RESOURCE'',''ORGANIZATION'',''SUBDIVISION'',''ENVIRONMENT'',''AUTHENTICATION'',''CAPABILITY'',''RBAC'')), CONSTRAINT CK_INX_IAM_POL_COND_OP CHECK (OPERATOR_NAME IN (''EQUALS'',''NOT_EQUALS'',''CONTAINS'',''EXISTS'')))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/

BEGIN EXECUTE IMMEDIATE 'CREATE TABLE INFRANEXUM_IAM_SOD_CONSTRAINT (ID VARCHAR2(36 CHAR) PRIMARY KEY, POLICY_ID VARCHAR2(36 CHAR) NOT NULL, ORGANIZATION_ID VARCHAR2(36 CHAR), FIRST_ROLE_ID VARCHAR2(36 CHAR) NOT NULL, SECOND_ROLE_ID VARCHAR2(36 CHAR) NOT NULL, REASON VARCHAR2(500 CHAR) NOT NULL, CREATED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL, CREATED_BY VARCHAR2(36 CHAR) NOT NULL, CONSTRAINT FK_INX_IAM_SOD_POLICY FOREIGN KEY (POLICY_ID) REFERENCES INFRANEXUM_IAM_ACCESS_POLICY(ID) ON DELETE CASCADE, CONSTRAINT FK_INX_IAM_SOD_ROLE1 FOREIGN KEY (FIRST_ROLE_ID) REFERENCES INFRANEXUM_IAM_ROLE(ID), CONSTRAINT FK_INX_IAM_SOD_ROLE2 FOREIGN KEY (SECOND_ROLE_ID) REFERENCES INFRANEXUM_IAM_ROLE(ID), CONSTRAINT UQ_INX_IAM_SOD_PAIR UNIQUE(POLICY_ID,FIRST_ROLE_ID,SECOND_ROLE_ID), CONSTRAINT CK_INX_IAM_SOD_UUID CHECK (REGEXP_LIKE(ID,''^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'')), CONSTRAINT CK_INX_IAM_SOD_DIST CHECK (FIRST_ROLE_ID<>SECOND_ROLE_ID))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/
BEGIN EXECUTE IMMEDIATE 'CREATE INDEX IX_INX_IAM_SOD_LOOKUP ON INFRANEXUM_IAM_SOD_CONSTRAINT(ORGANIZATION_ID,FIRST_ROLE_ID,SECOND_ROLE_ID)'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/

MERGE INTO INFRANEXUM_IAM_ACCESS_POLICY t USING (SELECT '00000000-0000-7000-8000-000000000110' id FROM dual) s ON (t.ID=s.id) WHEN NOT MATCHED THEN INSERT(ID,ORGANIZATION_ID,CODE,POLICY_VERSION,OWNER_ID,PURPOSE,PRIORITY,SCOPE_KIND,SUBDIVISION_ID,STATE,EFFECTIVE_FROM,APPROVED_BY,APPROVED_AT,ACTIVATED_AT,DEPRECATED_AT,RETIRED_AT,CREATED_AT,UPDATED_AT) VALUES(s.id,NULL,'system.rbac-bridge',1,'00000000-0000-7000-8000-000000000001','Preserve RBAC permits while advanced authorization policies are introduced.',0,'PLATFORM',NULL,'ACTIVE',TO_TIMESTAMP_TZ('2026-08-14 00:00:00 +00:00','YYYY-MM-DD HH24:MI:SS TZH:TZM'),'00000000-0000-7000-8000-000000000001',TO_TIMESTAMP_TZ('2026-08-14 00:00:00 +00:00','YYYY-MM-DD HH24:MI:SS TZH:TZM'),TO_TIMESTAMP_TZ('2026-08-14 00:00:00 +00:00','YYYY-MM-DD HH24:MI:SS TZH:TZM'),NULL,NULL,TO_TIMESTAMP_TZ('2026-08-14 00:00:00 +00:00','YYYY-MM-DD HH24:MI:SS TZH:TZM'),TO_TIMESTAMP_TZ('2026-08-14 00:00:00 +00:00','YYYY-MM-DD HH24:MI:SS TZH:TZM'));
MERGE INTO INFRANEXUM_IAM_ACCESS_POLICY_RULE t USING (SELECT '00000000-0000-7000-8000-000000000111' id FROM dual) s ON (t.ID=s.id) WHEN NOT MATCHED THEN INSERT(ID,POLICY_ID,POSITION_NO,EFFECT,ACTION_SELECTOR,RESOURCE_TYPE,OBLIGATIONS_CSV,ADVICE) VALUES(s.id,'00000000-0000-7000-8000-000000000110',1,'PERMIT','*','*','','RBAC permit bridged into advanced authorization.');
MERGE INTO INFRANEXUM_IAM_ACCESS_POLICY_CONDITION t USING (SELECT '00000000-0000-7000-8000-000000000111' rule_id,1 position_no FROM dual) s ON (t.RULE_ID=s.rule_id AND t.POSITION_NO=s.position_no) WHEN NOT MATCHED THEN INSERT(RULE_ID,POSITION_NO,SOURCE_NAME,ATTRIBUTE_NAME,OPERATOR_NAME,EXPECTED_VALUE) VALUES(s.rule_id,s.position_no,'RBAC','permitted','EQUALS','true');
